create index driver_tracking_booking_business_fk_idx on public.driver_tracking_sessions(booking_id,business_id);
create index driver_tracking_branch_business_fk_idx on public.driver_tracking_sessions(branch_id,business_id);
create index driver_tracking_driver_business_fk_idx on public.driver_tracking_sessions(driver_user_id,business_id);
create index driver_tracking_machine_business_fk_idx on public.driver_tracking_sessions(machine_id,business_id);
create index machine_location_booking_business_fk_idx on public.machine_location_updates(booking_id,business_id);
create index machine_location_branch_business_fk_idx on public.machine_location_updates(branch_id,business_id);
create index machine_location_driver_business_fk_idx on public.machine_location_updates(driver_user_id,business_id);
create index machine_location_machine_business_fk_idx on public.machine_location_updates(machine_id,business_id);
create index machine_location_assignment_fk_idx on public.machine_location_updates(assignment_id);
create index notifications_booking_business_fk_idx on public.notifications(booking_id,business_id);
create index notifications_branch_business_fk_idx on public.notifications(branch_id,business_id);
drop policy "staff read business tracking sessions" on public.driver_tracking_sessions;
drop policy "drivers read own tracking sessions" on public.driver_tracking_sessions;
create policy "staff and assigned drivers read tracking sessions" on public.driver_tracking_sessions for select to authenticated using(business_id=(select private.current_business_id()) and ((select private.can_manage_business()) or driver_user_id=(select auth.uid())));
grant insert on public.driver_tracking_sessions to authenticated;
grant update(ended_at) on public.driver_tracking_sessions to authenticated;
create policy "drivers start own tracking sessions" on public.driver_tracking_sessions for insert to authenticated with check(driver_user_id=(select auth.uid()) and business_id=(select private.current_business_id()) and (select private.current_app_role())='driver' and ended_at is null and exists(select 1 from public.booking_assignments a join public.bookings b on b.id=a.booking_id and b.business_id=a.business_id where a.id=driver_tracking_sessions.assignment_id and a.driver_user_id=(select auth.uid()) and a.active and b.status='in_progress'));
create policy "drivers stop own tracking sessions" on public.driver_tracking_sessions for update to authenticated using(driver_user_id=(select auth.uid()) and business_id=(select private.current_business_id()) and ended_at is null) with check(driver_user_id=(select auth.uid()) and business_id=(select private.current_business_id()) and ended_at is not null);
drop policy "staff read business machine locations" on public.machine_location_updates;
drop policy "drivers read own machine locations" on public.machine_location_updates;
create policy "staff and assigned drivers read machine locations" on public.machine_location_updates for select to authenticated using(business_id=(select private.current_business_id()) and ((select private.can_manage_business()) or driver_user_id=(select auth.uid())));
grant insert on public.machine_location_updates to authenticated;
grant usage,select on sequence public.machine_location_updates_id_seq to authenticated;
create policy "drivers write own active session locations" on public.machine_location_updates for insert to authenticated with check(driver_user_id=(select auth.uid()) and business_id=(select private.current_business_id()) and (select private.current_app_role())='driver' and exists(select 1 from public.driver_tracking_sessions s join public.booking_assignments a on a.id=s.assignment_id and a.active join public.bookings b on b.id=s.booking_id and b.status='in_progress' where s.id=machine_location_updates.tracking_session_id and s.driver_user_id=(select auth.uid()) and s.ended_at is null and s.business_id=machine_location_updates.business_id and s.machine_id=machine_location_updates.machine_id and s.assignment_id=machine_location_updates.assignment_id));
drop policy "staff read business notifications" on public.notifications;
drop policy "drivers read own notifications" on public.notifications;
create policy "staff and recipients read notifications" on public.notifications for select to authenticated using(business_id=(select private.current_business_id()) and (recipient_user_id=(select auth.uid()) or ((select private.can_manage_business()) and audience in ('owner','manager'))));
drop policy "managers update machines" on public.machines;
drop policy "drivers release own completed machines" on public.machines;
create policy "managers or assigned drivers update machines" on public.machines for update to authenticated using(business_id=(select private.current_business_id()) and ((select private.can_manage_business()) or exists(select 1 from public.booking_assignments a where a.machine_id=machines.id and a.driver_user_id=(select auth.uid()) and a.active))) with check(business_id=(select private.current_business_id()) and ((select private.can_manage_business()) or (status='available' and exists(select 1 from public.booking_assignments a join public.bookings b on b.id=a.booking_id and b.business_id=a.business_id where a.machine_id=machines.id and a.driver_user_id=(select auth.uid()) and a.active and b.status='completed'))));
